CREATE TABLE IF NOT EXISTS songs (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(200) NOT NULL, artist VARCHAR(200) NOT NULL, album VARCHAR(200) NOT NULL, genre VARCHAR(100) NOT NULL, duration INTERVAL NOT NULL, release_date DATE NOT NULL);
CREATE TABLE IF NOT EXISTS playlists (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id VARCHAR(200) NOT NULL, playlist_name VARCHAR(200) NOT NULL, created_date TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS "songPlaylist" (song_id INTEGER NOT NULL REFERENCES songs(id) ON DELETE CASCADE, playlist_id INTEGER NOT NULL REFERENCES playlists(id) ON DELETE CASCADE, PRIMARY KEY(song_id, playlist_id));
CREATE INDEX IF NOT EXISTS ix_playlists_user_id ON playlists(user_id);
